<script>
if('serviceWorker' in navigator){navigator.serviceWorker.register('/sw.js').catch(()=>{});}

marked.setOptions({breaks:true,gfm:true});
const ICONS={bash:'💻',read_file:'📄',write_file:'✏️',edit_file:'🔧',list_directory:'📁',glob:'🔍',grep:'🔎',delete_file:'🗑️',move_file:'📦',web_search:'🌐',web_fetch:'🌍',screenshot_url:'📸',database_query:'🗄️',http_request:'📡',view_env_vars:'🔑',git_operation:'🌿',spawn_subagent:'🤖',memory_read:'🧠',memory_write:'💾',agent_note:'📝'};

let convs=JSON.parse(localStorage.getItem('ag_v1')||'[]');
let aid=null,running=false,paused=false,atid=null;
let aSSE=null,timerIv=null,tStart=null,pollIv=null,stopped=false;
let srchTmr=null,allTasks={},uploads=[];

const $=id=>document.getElementById(id);
function save(){localStorage.setItem('ag_v1',JSON.stringify(convs))}
function gc(id){return convs.find(c=>c.id===id)}
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2)}
function scrl(){const m=$('msgs');m.scrollTop=m.scrollHeight}

function newChat(){
  const id=uid();
  convs.unshift({id,title:'New task',messages:[],taskId:null,created:Date.now()});
  save();loadConv(id);
}

function loadConv(id){
  aid=id;
  const c=gc(id),el=$('msgs');
  el.innerHTML='';
  if(!c.messages.length)showEmpty();
  else{c.messages.forEach(m=>{if(m.role==='user')renderU(m.content,false);else renderA(m.content,m.tools||[],false,m.mid);});scrl();}
  $('tbtitle').textContent=c.title||'Agent';
  renderSB();updPB();
}

function sw(tab){
  document.querySelectorAll('.st').forEach(b=>b.classList.toggle('on',b.dataset.tab===tab));
  document.querySelectorAll('.tp').forEach(p=>p.classList.toggle('on',p.id===tp-${tab}));
}

function renderSB(){
  const el=$('cl');el.innerHTML='';
  convs.forEach(c=>{
    const t=c.taskId?allTasks[c.taskId]:null;
    const st=t?(t.paused?'paused':t.status):'done';
    const d=document.createElement('div');
    d.className='ci'+(c.id===aid?' on':'');
    d.innerHTML=<div class="sd ${st}"></div><div class="ct">${esc(c.title||'New task')}</div>;
    d.onclick=()=>{if(c.id!==aid){doStop();loadConv(c.id);}};
    el.appendChild(d);
  });
}

function renderTasks(){
  const el=$('tptasksinner');el.innerHTML='';
  const all=Object.entries(allTasks).sort((a,b)=>b[1].createda[1].created);
  const running=all.filter(([,t])=>!['done','failed','cancelled'].includes(t.status));
  const badge=$('rbadge');
  badge.textContent=running.length;badge.style.display=running.length?'inline':'none';
  all.slice(0,30).forEach(([tid,t])=>{
    const st=t.paused?'paused':t.status;
    const conv=convs.find(c=>c.taskId===tid);
    const card=document.createElement('div');
    card.className='tc'+(tid===atid?' act':'');
    card.innerHTML=<div class="tct">
      <span class="tpill ${st}">${st.toUpperCase()}</span>
      <span class="ttl">${esc(t.title||tid.slice(0,12))}</span>
      <div class="tab">
        ${st==='running'?<button class="tabtn" title="Pause" onclick="event.stopPropagation();aPause('${tid}')">⏸</button>:''}
        ${st==='paused'?<button class="tabtn" title="Resume" onclick="event.stopPropagation();aResume('${tid}')">▶</button>:''}
        ${['running','paused'].includes(st)?<button class="tabtn" title="Cancel" onclick="event.stopPropagation();aCancel('${tid}')">✕</button>:''}
      </div>
    </div>;
    if(conv)card.onclick=()=>{doStop();loadConv(conv.id);};
    el.appendChild(card);
  });
  if(!all.length)el.innerHTML='<div style="padding:18px;textalign:center;color:var(t3);fontsize:12px">No tasks yet</div>';
}

async function pollAll(){
  try{
    const r=await fetch('/api/tasks');if(!r.ok)return;
    const list=await r.json();
    allTasks={};list.forEach(t=>{allTasks[t.task_id]=t;});
    renderTasks();renderSB();updPB();
  }catch{}
}
setInterval(pollAll,3000);

function updPB(){
  const bar=$('pb');
  const run=Object.entries(allTasks).filter(([,t])=>['running','paused'].includes(t.paused?'paused':t.status));
  if(run.length<=1){bar.classList.remove('vis');bar.innerHTML='';return;}
  bar.classList.add('vis');bar.innerHTML='';
  run.forEach(([tid,t])=>{
    const dot=t.paused?'paused':t.status==='running'?'running':'done';
    const ch=document.createElement('div');
    ch.className='pch'+(tid===atid?' ach':'');
    ch.innerHTML=<div class="pchd ${dot}"></div><span class="pchl">${esc((t.title||tid).slice(0,26))}</span>;
    const conv=convs.find(c=>c.taskId===tid);
    if(conv)ch.onclick=()=>{doStop();loadConv(conv.id);};
    bar.appendChild(ch);
  });
}

async function aPause(tid){await fetch(/api/task/${tid}/pause,{method:'POST'});if(tid===atid)setPaused(true);}
async function aResume(tid){await fetch(/api/task/${tid}/resume,{method:'POST'});if(tid===atid)setPaused(false);}
async function aCancel(tid){if(!confirm('Cancel this task?'))return;await fetch(/api/task/${tid}/cancel,{method:'POST'});}

function showEmpty(){
  const el=$('msgs');
  if($('est'))return;
  const e=document.createElement('div');e.className='est';e.id='est';
  e.innerHTML=<div class="eico">✦</div>;
  el.appendChild(e);
}
function rmEmpty(){const e=$('est');if(e)e.remove();}

function renderU(text,scroll=true){
  rmEmpty();
  const el=document.createElement('div');el.className='msg usr';
  el.innerHTML=<div class="av u">You</div><div class="bbl"><div class="utxt">${esc(text)}</div></div>;
  $('msgs').appendChild(el);
  if(scroll)scrl();
}

function renderA(text,tools,scroll=true,msgId){
  const el=document.createElement('div');el.className='msg';
  if(msgId)el.dataset.mid=msgId;
  el.dataset.idx=document.querySelectorAll('.msg').length;
  const th=(tools||[]).map(t=>mkTB(t)).join('');
  el.innerHTML=<div class="av ai">✦</div><div class="bbl">${th}<div class="aic">${marked.parse(text||'')}</div><div class="hov">
    <button class="hb" onclick="forkHere(this)">⎇ Fork</button>
    <button class="hb" onclick="copyHere(this)">⎘ Copy</button>
  </div></div>;
  el.querySelectorAll('pre code').forEach(b=>hljs.highlightElement(b));
  $('msgs').appendChild(el);
  if(scroll)scrl();
}

function mkTB(t){
  const icon=ICONS[t.name]||'⚙️';
  const prev=tPrev(t.name,t.args||{});
  const isErr=t.error||false;
  const sCls=isErr?'er':'dn';const sTxt=isErr?'✗ Error':'✓ Done';
  const ah=prev?<div class="tar">${esc(prev)}</div>:'';
  const rh=t.result?<div class="trr"><pre>${esc(t.result)}</pre></div>:'';
  return <div class="tbl"><div class="thdr" onclick="this.parentElement.classList.toggle('op')"><span class="tico">${icon}</span><span class="tnm">${t.name}</span>${prev?<span class="tapv">${esc(prev.slice(0,50))}</span>:''}<span class="tst ${sCls}">${sTxt}</span><span class="tchv">▼</span></div><div class="tdet">${ah}${rh}</div></div>;
}

function tPrev(name,args){
  const m={bash:'command',read_file:'path',write_file:'path',edit_file:'path',delete_file:'path',list_directory:'path',glob:'pattern',grep:'pattern',web_search:'query',web_fetch:'url',screenshot_url:'url',git_operation:'command',agent_note:'note',spawn_subagent:'task',memory_write:'key',memory_read:'key'};
  if(m[name]&&args[m[name]])return String(args[m[name]]);
  if(name==='move_file')return ${args.source||''} → ${args.destination||''};
  if(name==='http_request')return ${args.method||'GET'} ${args.url||''};
  if(name==='database_query')return String(args.sql||'').slice(0,80);
  return JSON.stringify(args).slice(0,80);
}

function forkHere(btn){
  const msgEl=btn.closest('.msg');
  const idx=parseInt(msgEl.dataset.idx||'0');
  const p=prompt('Fork from this point — new direction:');
  if(!p||!aid)return;
  const c=gc(aid);if(!c||!c.taskId)return alert('No task ID.');
  fetch(/api/task/${c.taskId}/fork,{method:'POST',headers:{'ContentType':'application/json'},body:JSON.stringify({message_index:idx,message:p})})
    .then(r=>r.json()).then(d=>{if(d.task_id)mkFork(d.task_id,p);});
}

function forkAll(){
  const c=gc(aid);if(!c||!c.taskId)return alert('No completed task to fork.');
  const p=window.prompt('Fork from end — new direction:');if(!p)return;
  fetch(/api/task/${c.taskId}/fork,{method:'POST',headers:{'ContentType':'application/json'},body:JSON.stringify({message:p})})
    .then(r=>r.json()).then(d=>{if(d.task_id)mkFork(d.task_id,p);else alert('Fork failed: '+JSON.stringify(d));});
}

function mkFork(taskId,p){
  const fid=uid();
  convs.unshift({id:fid,title:'Fork: '+p.slice(0,45),messages:[],taskId,created:Date.now()});
  save();loadConv(fid);startListen(taskId);setRunning(true);
}

function copyHere(btn){
  const c=btn.closest('.bbl').querySelector('.aic');
  if(c)navigator.clipboard.writeText(c.innerText).catch(()=>{});
}

function startTimer(){
  tStart=Date.now();const el=$('timer');
  el.style.display='block';el.className='rt';
  if(timerIv)clearInterval(timerIv);
  timerIv=setInterval(()=>{const s=Math.floor((Date.now()tStart)/1000);el.textContent=${Math.floor(s/60)}:${(s%60).toString().padStart(2,'0')};},1000);
}
function stopTimer(){if(timerIv)clearInterval(timerIv);timerIv=null;$('timer').style.display='none';}

function setRunning(v){
  running=v;if(!v)paused=false;
  $('sendbtn').disabled=v;
  $('sbtn').classList.toggle('sh',v);
  $('pbtn').classList.toggle('sh',v&&!paused);
  $('rebtn').classList.toggle('sh',v&&paused);
  $('inj').style.display=v?'block':'none';
  $('pb2').style.display='none';
  $('fbt').style.display=!v&&aid&&gc(aid)?.taskId?'flex':'none';
  if(v)startTimer();else stopTimer();
  renderSB();
}

function setPaused(v){
  paused=v;
  $('pbtn').classList.toggle('sh',running&&!v);
