  const inp=$('injin'),msg=inp.value.trim();
  if(!msg||!atid)return;inp.value='';
  const r=await fetch(/api/task/${atid}/inject,{method:'POST',headers:{'ContentType':'application/json'},body:JSON.stringify({message:msg})});
  if(!r.ok){const d=await r.json();alert(d.error||'Inject failed');}
}

async function handleFiles(input){
  const files=Array.from(input.files);if(!files.length)return;
  const form=new FormData();files.forEach(f=>form.append('file',f));
  const upl=$('upl');
  const phs=files.map(f=>{const ch=document.createElement('div');ch.className='uch';ch.innerHTML=<span class="ucn">${esc(f.name)}</span><span style="color:var(--yel);font-size:10px">…</span>;upl.appendChild(ch);return ch;});
  try{
    const r=await fetch('/api/upload',{method:'POST',body:form});
    const d=await r.json();phs.forEach(c=>c.remove());
    if(d.saved){d.saved.forEach(s=>{const ch=document.createElement('div');ch.className='uch';ch.innerHTML=<span class="ucn">${esc(s.filename)}</span><button class="ucrm" onclick="rmUp(this,'${esc(s.path)}')">✕</button>;upl.appendChild(ch);uploads.push(s);});}
    if(d.errors?.length)alert('Upload errors:\n'+d.errors.join('\n'));
  }catch(e){phs.forEach(c=>c.remove());alert('Upload failed: '+e.message);}
  input.value='';
}

