setTimeout(showIOSInstallHint, 2000);

// ─── Haptic feedback (iOS Safari 10+) ───
function haptic(style = 'light') {
  if (window.DeviceMotionEvent && typeof DeviceMotionEvent.requestPermission === 'function') return; // iOS 13+ kér engedélyt
  try {
    const patterns = { light: [10], medium: [20], heavy: [30], success: [10, 50, 10], error: [50, 30, 50] };
    if ('vibrate' in navigator) navigator.vibrate(patterns[style] || [10]);
  } catch {}
}
// Minden gombra
document.addEventListener('click', e => {
  if (e.target.closest('button')) haptic('light');
});

// ─── Badge API ───
async function setBadge(count) {
  if ('setAppBadge' in navigator) {
    try { await navigator.setAppBadge(count); } catch {}
  }
}
async function clearBadge() {
  if ('clearAppBadge' in navigator) {
    try { await navigator.clearAppBadge(); } catch {}
  }
}

// ─── Web Push ───
async function subscribePush() {
  if (!('PushManager' in window)) return;
  try {
    const reg = await navigator.serviceWorker.ready;
    const existing = await reg.pushManager.getSubscription();
    if (existing) return existing;
    const sub = await reg.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: urlBase64ToUint8Array('YOUR_VAPID_PUBLIC_KEY_HERE')
    });
    await fetch('/api/push/subscribe', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(sub) });
    return sub;
  } catch (e) { console.warn('Push subscribe failed:', e); }
}

function urlBase64ToUint8Array(base64String) {
  const padding = '='.repeat((4 - base64String.length % 4) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const raw = window.atob(base64);
  const arr = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) arr[i] = raw.charCodeAt(i);
  return arr;
}

// ─── Notification permission kérés (user gesture-ből) ───
async function requestNotifPermission() {
  if (Notification.permission === 'default') {
    const p = await Notification.requestPermission();
    if (p === 'granted') await subscribePush();
  }
}
// Első send() után kérjük
const _origSend = window.send;
let notifAsked = false;
window.send = async function() {
  await _origSend?.apply(this, arguments);
  if (!notifAsked) { notifAsked = true; requestNotifPermission(); }
};

// ─── Background Sync ───
async function queueMessageForSync(data) {
  const reg = await navigator.serviceWorker.ready;
  if ('sync' in reg) {
    const db = await openIndexedDB();
    const tx = db.transaction('pending', 'readwrite');
    tx.objectStore('pending').add({ ...data, id: Date.now() });
    await reg.sync.register('send-message');
  }
}

// ─── Periodic Background Sync ───
async function registerPeriodicSync() {
  const reg = await navigator.serviceWorker.ready;
  if ('periodicSync' in reg) {
    try {
      const status = await navigator.permissions.query({ name: 'periodic-background-sync' });
      if (status.state === 'granted') {
        await reg.periodicSync.register('poll-tasks', { minInterval: 5 * 60 * 1000 });
      }
    } catch {}
  }
}
registerPeriodicSync();

